def _normalized_resource(path):
    segments = [segment.strip() for segment in str(path).split("/") if segment.strip()]
    normalized = []
    for segment in segments:
        if segment in {"1", ":id", "{id}", "<int:id>", "<int:pk>"}:
            normalized.append("<int:pk>")
        elif segment.startswith(":") or (
            segment.startswith("{") and segment.endswith("}")
        ):
            normalized.append("<int:pk>")
        else:
            normalized.append(segment)
    return "/".join(normalized) + "/"


def _assert_unique(items, description):
    grouped = {}
    for object_id, key in items:
        grouped.setdefault(key, []).append(object_id)
    duplicates = [ids for ids in grouped.values() if len(ids) > 1]
    if duplicates:
        raise RuntimeError(
            f"No se puede normalizar {description}: "
            f"hay registros duplicados {duplicates[:10]}."
        )


def normalize_existing_rbac(apps, schema_editor):
    database = schema_editor.connection.alias
    Permission = apps.get_model("security", "Permission")
    Role = apps.get_model("security", "Role")
    UserRole = apps.get_model("security", "UserRole")

    roles = list(Role.objects.using(database).order_by("pk"))
    _assert_unique(
        ((role.pk, role.name.strip().upper()) for role in roles),
        "nombres de roles",
    )
    permissions = list(Permission.objects.using(database).order_by("pk"))
    _assert_unique(
        (
            (
                permission.pk,
                (
                    permission.http_method.strip().upper(),
                    _normalized_resource(permission.resource),
                ),
            )
            for permission in permissions
        ),
        "rutas y métodos de permisos",
    )

    assignments = UserRole.objects.using(database).values_list(
        "pk", "role_id", "auth_user_id", "user_id"
    )
    auth_assignments = []
    legacy_assignments = []
    for assignment_id, role_id, auth_user_id, legacy_user_id in assignments:
        if auth_user_id is not None:
            auth_assignments.append((assignment_id, (auth_user_id, role_id)))
        if legacy_user_id is not None:
            legacy_assignments.append((assignment_id, (legacy_user_id, role_id)))
    _assert_unique(auth_assignments, "asignaciones de usuario autenticado")
    _assert_unique(legacy_assignments, "asignaciones de usuario legado")

    for role in roles:
        role.name = role.name.strip().upper()
    if roles:
        Role.objects.using(database).bulk_update(roles, ["name"])

    for permission in permissions:
        permission.http_method = permission.http_method.strip().upper()
        permission.resource = _normalized_resource(permission.resource)
    if permissions:
        Permission.objects.using(database).bulk_update(
            permissions,
            ["http_method", "resource"],
        )


